-- ----------------------------
-- Table structure for basisname
-- ----------------------------
DROP TABLE IF EXISTS `basisname`;
CREATE TABLE `basisname` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `basis` varchar(100) DEFAULT NULL COMMENT '判定依据',
  `basisName` varchar(255) DEFAULT NULL COMMENT '判定依据名称',
  `note` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1152 DEFAULT CHARSET=utf8;

