-- ----------------------------
-- Table structure for contract
-- ----------------------------
DROP TABLE IF EXISTS `contract`;
CREATE TABLE `contract` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `htbh` varchar(10) DEFAULT NULL COMMENT '合同编号',
  `customerId` varchar(10) DEFAULT NULL COMMENT '委托单位ID-(外键-单位名称)',
  `content` text COMMENT '合同内容摘要',
  `total` float(10,2) DEFAULT NULL COMMENT '合同金额',
  `htcoin` float(10,2) DEFAULT NULL COMMENT '合同币',
  `htcoin_remain` float(10,2) DEFAULT NULL COMMENT '合同余币',
  `unitcost` float(10,2) DEFAULT NULL COMMENT '币值',
  `isreceive` varchar(10) DEFAULT NULL COMMENT '是否已收费',
  `alive_status` varchar(10) DEFAULT NULL COMMENT '激活状态-合同币是否可用',
  `date` varchar(10) DEFAULT NULL COMMENT '合同日期',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of contract
-- ----------------------------

-- ----------------------------
-- Table structure for customer
-- ----------------------------
DROP TABLE IF EXISTS `customer`;
CREATE TABLE `customer` (
  `id` smallint NOT NULL AUTO_INCREMENT COMMENT '编号（主键）',
  `company` varchar(50) NOT NULL COMMENT '单位名称',
  `lxr` varchar(10) NOT NULL COMMENT '联系人',
  `leader` varchar(10) DEFAULT NULL COMMENT '负责人',
  `lxrMobileNo` varchar(20) DEFAULT NULL COMMENT '联系人手机',
  `leaderMobileNO` varchar(20) DEFAULT NULL COMMENT '负责人手机',
  `addr` varchar(80) DEFAULT NULL COMMENT '单位地址',
  `type` varchar(40) DEFAULT NULL COMMENT '主营类别',
  `bank` varchar(20) DEFAULT NULL COMMENT '开户行',
  `bankNo` varchar(20) DEFAULT NULL COMMENT '银行账号',
  `status` varchar(20) DEFAULT NULL COMMENT '状态',
  `fenlei` varchar(50) DEFAULT NULL,
  `kaituoren` varchar(50) DEFAULT NULL,
  `weihuren` varchar(50) DEFAULT NULL,
  `diqu` varchar(255) DEFAULT NULL,
  `pinyin` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of customer
-- ----------------------------
