-- ----------------------------
-- Table structure for lib
-- ----------------------------
DROP TABLE IF EXISTS `lib`;
CREATE TABLE `lib` (
  `productId` varchar(10) NOT NULL,
  `xh` smallint NOT NULL,
  `testItem` varchar(255) DEFAULT NULL,
  `basis` varchar(100) DEFAULT NULL,
  `mathod` varchar(100) DEFAULT NULL,
  `stdValue` varchar(50) DEFAULT NULL,
  `num_lowerst` varchar(20) DEFAULT NULL,
  `method_note` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`productId`,`xh`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

