-- ----------------------------
-- Table structure for prj_detail
-- ----------------------------
DROP TABLE IF EXISTS `prj_detail`;
CREATE TABLE `prj_detail` (
  `project_bh` varchar(20) NOT NULL COMMENT '项目编号（project_bh+item_xh联合主键）',
  `item_xh` smallint NOT NULL COMMENT '单项序号（project_bh+item_xh联合主键）',
  `testItem` varchar(100) NOT NULL COMMENT '检测单项名称',
  `stdValue` varchar(255) DEFAULT NULL COMMENT '指标要求',
  `basis` varchar(100) DEFAULT NULL COMMENT '检验依据',
  `mathod` varchar(100) DEFAULT NULL COMMENT '检验方法',
  `method_note` varchar(100) DEFAULT NULL COMMENT '方法备注',
  `userId_jyy` varchar(10) DEFAULT NULL COMMENT '检验员ID',
  `jyResult` varchar(255) DEFAULT NULL COMMENT '检验结果',
  `jyResult_note` varchar(100) DEFAULT NULL,
  `item_evaluate` varchar(10) DEFAULT NULL COMMENT '单项评价',
  `num_lowerst` varchar(30) DEFAULT NULL COMMENT '最低检出限',
  PRIMARY KEY (`project_bh`,`item_xh`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

