-- ----------------------------
-- Table structure for project
-- ----------------------------
DROP TABLE IF EXISTS `project`;
CREATE TABLE `project` (
  `id_nj` bigint NOT NULL AUTO_INCREMENT,
  `bh` varchar(20) DEFAULT NULL COMMENT '项目编号',
  `customerId` varchar(10) DEFAULT NULL COMMENT '客户单位ID',
  `productName` varchar(40) DEFAULT NULL COMMENT '产品名称',
  `ggxh` varchar(30) DEFAULT NULL COMMENT '规格型号',
  `ypsb` varchar(30) DEFAULT NULL COMMENT '样品商标',
  `ypdj` varchar(30) DEFAULT NULL COMMENT '样品等级',
  `ypbz` varchar(255) DEFAULT NULL COMMENT '样品备注',
  `jymd` varchar(20) DEFAULT NULL COMMENT '检验目的',
  `jylb` varchar(20) DEFAULT NULL COMMENT '检验类别',
  `jylx` varchar(60) DEFAULT NULL COMMENT '检验类型',
  `date_sy` varchar(10) DEFAULT NULL COMMENT '送样日期',
  `date_cy` varchar(10) DEFAULT NULL COMMENT '抽样日期',
  `date_yywc` varchar(10) DEFAULT NULL COMMENT '预约完成日期',
  `userId_cy` varchar(20) DEFAULT NULL COMMENT '抽样人',
  `cyjs` varchar(20) DEFAULT NULL COMMENT '抽样基数',
  `cyaddr` varchar(80) DEFAULT NULL COMMENT '抽样地点',
  `isUpfile` varchar(2) DEFAULT NULL COMMENT '是否已上传抽样单',
  `customerId_scdw` varchar(10) DEFAULT NULL COMMENT '生产单位ID',
  `customerId_sjdw` varchar(10) DEFAULT NULL COMMENT '受检单位ID',
  `date_sc` varchar(30) DEFAULT NULL COMMENT '生产日期 或原编号 ',
  `scBatch` varchar(20) DEFAULT NULL COMMENT '生产批号',
  `ypNum` varchar(20) DEFAULT NULL COMMENT '样品数量',
  `byNum` varchar(20) DEFAULT NULL COMMENT '备样量',
  `otherFile` varchar(30) DEFAULT NULL COMMENT '随样品所附资料',
  `ypSaveReq` varchar(30) DEFAULT NULL COMMENT '样品存储要求',
  `yyProcess` varchar(30) DEFAULT NULL COMMENT '余样处理',
  `getReport` varchar(30) DEFAULT NULL COMMENT '报告领取方式',
  `isFitTestReq` varchar(4) DEFAULT NULL COMMENT '是否符合检验要求',
  `ypCharacter` varchar(30) DEFAULT NULL COMMENT '样品性状',
  `ypSituation` varchar(30) DEFAULT NULL COMMENT '样品状况',
  `testLib` varchar(50) DEFAULT NULL COMMENT '项目检验标准库',
  `remarks_register` varchar(255) DEFAULT NULL COMMENT '项目登记备注',
  `remarks_div` varchar(255) DEFAULT NULL COMMENT '项目分解备注',
  `remarks_agree` varchar(255) DEFAULT NULL COMMENT '分解批准备注',
  `remarks_arrange` varchar(255) DEFAULT NULL COMMENT '任务安排备注',
  `remarks_examine` varchar(255) DEFAULT NULL COMMENT '审核备注（可退回）',
  `remarks_verify` varchar(255) DEFAULT NULL COMMENT '授权备注（可退回）',
  `remarks_financial` varchar(255) DEFAULT NULL COMMENT '财务审核备注信息',
  `state_register` varchar(8) DEFAULT NULL COMMENT '登记状态',
  `state_div` varchar(8) DEFAULT NULL COMMENT '项目分解状态',
  `state_arrange` varchar(8) DEFAULT NULL COMMENT '任务安排状态',
  `state_comlete` varchar(8) DEFAULT NULL COMMENT '项目级检验完成状态',
  `state_agree` varchar(8) DEFAULT NULL COMMENT '批准状态',
  `state_examine` varchar(8) DEFAULT NULL COMMENT '审核状态',
  `state_verify` varchar(8) DEFAULT NULL COMMENT '授权状态',
  `state_financial` varchar(8) DEFAULT NULL COMMENT '财务审核状态',
  `state_cwprocess` varchar(8) DEFAULT NULL COMMENT '财务意见处理状态',
  `state_reportprint` varchar(8) DEFAULT NULL COMMENT '证书打印状态',
  `state_isstop` varchar(8) DEFAULT NULL COMMENT '中止状态',
  `userId_reg` varchar(10) DEFAULT NULL COMMENT '项目登记人',
  `date_reg` varchar(10) DEFAULT NULL COMMENT '项目登记日期',
  `userId_div` varchar(10) DEFAULT NULL COMMENT '项目分解人',
  `date_div` varchar(10) DEFAULT NULL COMMENT '项目分解日期',
  `userId_agree` varchar(10) DEFAULT NULL COMMENT '项目分解批准人',
  `date_agree` varchar(10) DEFAULT NULL COMMENT '项目分解批准日期',
  `userId_arrange` varchar(10) DEFAULT NULL COMMENT '任务安排人',
  `date_arrange` varchar(10) DEFAULT NULL COMMENT '安排日期',
  `userId_examine` varchar(10) DEFAULT NULL COMMENT '审核人',
  `userId_verify` varchar(10) DEFAULT NULL COMMENT '授权人',
  `date_verify` varchar(10) DEFAULT NULL COMMENT '授权日期',
  `date_jystart` varchar(10) DEFAULT NULL COMMENT '检验起始日期',
  `date_jycomplete` varchar(10) DEFAULT NULL COMMENT '检验完成日期',
  `date_downreport` varchar(10) DEFAULT NULL COMMENT '检验报告下载日期',
  `date_printreport` varchar(10) DEFAULT NULL COMMENT '检验报告打印日期',
  `jhmc` varchar(50) DEFAULT NULL COMMENT '计划名称（即采样单导入表中的“项目名称”）',
  `jhflag` varchar(50) DEFAULT NULL COMMENT '计划标识',
  `exstd` varchar(20) DEFAULT NULL COMMENT '执行标准',
  `price` varchar(10) DEFAULT NULL COMMENT '单价',
  `totalprice` varchar(10) DEFAULT NULL COMMENT '总价',
  `category` varchar(50) DEFAULT NULL COMMENT '食品大类（国标库）',
  `category_sub` varchar(50) DEFAULT NULL COMMENT '食品分类（自填）',
  `cybh` varchar(30) DEFAULT NULL COMMENT '抽样编号',
  `scdateflag` varchar(30) DEFAULT NULL COMMENT '省抽导入日期标志（相当于导入xls数据标志）',
  `result` varchar(10) DEFAULT NULL COMMENT '项目检验结论',
  `sfmethod` varchar(10) DEFAULT NULL COMMENT '收费方式-合同或收费',
  `htbh` varchar(10) DEFAULT NULL COMMENT '合同币编号',
  `htcoin` float(10,2) DEFAULT NULL COMMENT '合同币数',
  `subtotal` float(10,2) DEFAULT NULL COMMENT '收费额',
  `isreceived` varchar(10) DEFAULT NULL COMMENT '收费情况-已收、未收',
  `billno` varchar(10) DEFAULT NULL COMMENT '收据凭证号码',
  `fileno` varchar(10) DEFAULT NULL COMMENT '批件号码-领导批示件',
  `memo` text COMMENT '备注',
  `date_stamp` varchar(10) DEFAULT NULL COMMENT '盖章日期',
  `date_recfee` varchar(10) DEFAULT NULL COMMENT '收费日期',
  `sentreport` varchar(255) DEFAULT NULL COMMENT '报告快递记录',
  `taskno` varchar(30) DEFAULT NULL COMMENT '任务号',
  `taskbatchno` varchar(30) DEFAULT NULL COMMENT '任务批号',
  `dwname_sj_nj` varchar(40) DEFAULT NULL COMMENT '受检单位名称',
  `dwname_wt_nj` varchar(40) DEFAULT NULL COMMENT '委托单位名称',
  `dwname_sc_nj` varchar(40) DEFAULT NULL COMMENT '生产单位名称',
  `usergetmoney_nj` varchar(20) DEFAULT NULL COMMENT '收款人姓名',
  PRIMARY KEY (`id_nj`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8;

