-- ----------------------------
-- Table structure for sjtask
-- ----------------------------
DROP TABLE IF EXISTS `sjtask`;
CREATE TABLE `sjtask` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `taskno` varchar(30) DEFAULT NULL COMMENT '任务编号',
  `leader` varchar(30) DEFAULT NULL COMMENT '负责人或责任人',
  `source` varchar(100) DEFAULT NULL COMMENT '任务来源（如南通市市场管理局）',
  `region` varchar(50) DEFAULT NULL COMMENT '区域分类（如省级、市级、区级）',
  `note` varchar(255) DEFAULT NULL COMMENT '任务说明（任务相关情况在此说明）',
  `date` varchar(20) DEFAULT NULL COMMENT '任务接受日期',
  `taskname` varchar(50) DEFAULT 'null' COMMENT '任务名称',
  `taskxz` varchar(30) DEFAULT 'null' COMMENT '任务性质（委托送样、委托抽样、监督抽检）',
  `picino` varchar(30) DEFAULT 'null' COMMENT '批次',
  `xiaddate` varchar(20) DEFAULT 'null' COMMENT '任务下达日期',
  `wancdate` varchar(10) DEFAULT 'null' COMMENT '任务完成日期',
  `rwdji` varchar(10) DEFAULT 'null' COMMENT '任务等级',
  `yxlyaoq` varchar(50) DEFAULT 'null' COMMENT '阳性率要求',
  `chouyhj` varchar(10) DEFAULT 'null' COMMENT '抽样环节（生产、流通、餐饮）',
  `jcxm` varchar(40) DEFAULT 'null' COMMENT '检测项目（监抽全项、非去、全项。。。）',
  `chouystate` varchar(10) DEFAULT 'null' COMMENT '抽样完成标记',
  `state` varchar(10) DEFAULT 'null' COMMENT '任务名称',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8;

