-- ----------------------------
-- Table structure for sjtask_import_log
-- ----------------------------
DROP TABLE IF EXISTS `sjtask_import_log`;
CREATE TABLE `sjtask_import_log` (
  `marker` varchar(128) NOT NULL COMMENT '抽样单文件标识（xls 的 A1 单元格）',
  `original_name` varchar(255) NOT NULL COMMENT '原始文件名',
  `row_count` int NOT NULL DEFAULT '0' COMMENT '实际导入数据行数',
  `created_by` varchar(64) DEFAULT NULL COMMENT '导入人工号',
  `created_at` datetime NOT NULL COMMENT '导入时间',
  PRIMARY KEY (`marker`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='抽样单导入记录（防重复导入）';

-- ----------------------------
-- Table structure for sys
-- ----------------------------
DROP TABLE IF EXISTS `sys`;
CREATE TABLE `sys` (
  `id` smallint NOT NULL COMMENT '主键',
  `tnsw_no` varchar(10) DEFAULT NULL COMMENT 'QZSW项目最新编号',
  `tnsj_no` varchar(10) DEFAULT NULL COMMENT 'QZSG项目最新编号',
  `zzlevel` varchar(10) DEFAULT NULL COMMENT '资质级别',
  `permissioner` varchar(10) DEFAULT NULL COMMENT '批准人',
  `chief` varchar(10) DEFAULT NULL COMMENT '检验总负责',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

