-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `gh` varchar(10) NOT NULL,
  `name` varchar(10) NOT NULL,
  `password` varchar(10) NOT NULL,
  `userRoleId` varchar(4) NOT NULL,
  `deptId` varchar(20) DEFAULT NULL,
  `xueli` varchar(10) DEFAULT NULL,
  `zhicheng` varchar(10) DEFAULT NULL,
  `zy` varchar(20) DEFAULT NULL,
  `mobile` varchar(20) DEFAULT NULL,
  `email` varchar(20) DEFAULT NULL,
  `position` varchar(20) DEFAULT NULL,
  `certificate` varchar(20) DEFAULT NULL,
  `nature` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`gh`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

